const H = this.helpers;
const seg = n => { const i = $('Devocional: segredos').all().find(x => x.json.chave === n); return i ? String(i.json.valor || '') : ''; };
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36';
const acao = async (url, id, corpo, cookie) => {
  const r = await H.httpRequest({ method: 'POST', url, body: corpo, json: false, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true, disableFollowRedirect: true,
    headers: Object.assign({ 'Accept': 'text/x-component', 'Next-Action': id, 'Origin': 'https://painel.dtunnel.com.br', 'User-Agent': UA, 'Content-Type': 'text/plain;charset=UTF-8' }, cookie ? { Cookie: cookie } : {}) });
  let sc = r.headers['set-cookie'] || []; if (!Array.isArray(sc)) sc = [sc];
  return { status: r.statusCode, corpo: String(r.body || ''), cookie: sc.map(c => String(c).split(';')[0]).join('; ') };
};
const hoje = d => new Date(Date.now() + d * 86400000).toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }).slice(0, 10);
const senha = seg('dtunnel_senha');
if (!senha) return [{ json: { ok: false, erro: 'falta a senha do DTunnel na tabela segredos (dtunnel_senha)' } }];
const lg = await acao('https://painel.dtunnel.com.br/login', '405b519d2d62441fd421a3e0fd61901d6b0edfc4f6', JSON.stringify([{ email: seg('dtunnel_usuario') || seg('dtunnel_email') || 'jeanverasdesigner@gmail.com', password: senha }]));
if (!lg.cookie) return [{ json: { ok: false, erro: 'login no DTunnel falhou (status ' + lg.status + ')' } }];

const amanha = hoje(1); const img = 'https://raw.githubusercontent.com/TheB171/netliss-devocional/main/' + amanha.slice(0, 7) + '/' + amanha.slice(8, 10) + '.png';
const ex = await H.httpRequest({ method: 'GET', url: img, returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'arraybuffer', timeout: 30000 });
if (ex.statusCode !== 200) return [{ json: { ok: false, erro: 'a arte de amanhã (' + amanha + ') não está no GitHub: ' + img } }];
const base = await H.httpRequest({ method: 'GET', url: 'https://raw.githubusercontent.com/TheB171/netliss-devocional/main/config/app-config-base.json', json: false, timeout: 30000 });
const campos = String(base).split('@@IMG@@').join(img);
const r = await acao('https://painel.dtunnel.com.br/aplicativo', '406e4d4830b14b6030e120175022c93a06a50a328e', '[{"id":null,"userId":null,"fields":' + campos + ',"source":"default","isActive":true}]', lg.cookie);
const ok = r.status < 400 && !/"success":\s*false|"error"/i.test(r.corpo);
return [{ json: { ok, erro: ok ? '' : 'o DTunnel não aceitou a troca do fundo (status ' + r.status + '): ' + r.corpo.slice(0, 200), img } }];

